import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs: List<Int64> = [10, 20, 30]
    xs.add(40)
    io.println("size:${xs.size()}")
    match xs.removeAt(1) {
        Some(v) => { io.println("rm:${v}") }
        None => { io.println("rm:none") }
    }
    match xs.get(0) {
        Some(v) => { io.println("g0:${v}") }
        None => { io.println("g0:none") }
    }
    match xs.get(9) {
        Some(v) => { io.println("g9:${v}") }
        None => { io.println("g9:none") }
    }
    match xs.removeAt(9) {
        Some(v) => { io.println("r9:${v}") }
        None => { io.println("r9:none") }
    }
    io.println("size:${xs.size()}")
    return Ok(())
}
